package com.macle.royaleassist

import kotlinx.io.buffered
import kotlinx.io.files.Path
import kotlinx.io.files.SystemFileSystem
import kotlinx.io.readString

/** A test fixture under src/commonTest/resources ([FIXTURES_DIR] is generated by the build). */
fun readFixture(path: String): String =
    SystemFileSystem.source(Path(FIXTURES_DIR, path)).buffered().use { it.readString() }
